1	// Behaviour of each patch operation: add, remove, replace, move, copy, test.
2	import { describe, test } from 'node:test';
3	import assert from 'node:assert/strict';
4	import { applyPatch } from '../jsonpatch.mjs';
5	import { assertExact, assertNoSharing, assertPatchError, j } from './helpers.mjs';
6	
7	const add = (path, value) => ({ op: 'add', path, value });
8	const remove = (path) => ({ op: 'remove', path });
9	const replace = (path, value) => ({ op: 'replace', path, value });
10	const move = (from, path) => ({ op: 'move', from, path });
11	const copy = (from, path) => ({ op: 'copy', from, path });
12	const check = (path, value) => ({ op: 'test', path, value });
13	
14	// Table driver: each row is [name, doc, patch, expected result].
15	function runTable(rows) {
16	  for (const [name, doc, patch, expected] of rows) {
17	    test(name, () => assertExact(applyPatch(doc, patch), expected));
18	  }
19	}
20	
21	// Table driver: each row is [name, doc, patch, message, index].
22	function failTable(rows) {
23	  for (const [name, doc, patch, message, index = 0] of rows) {
24	    test(name, () => assertPatchError(doc, patch, message, index));
25	  }
26	}
