28	describe('add', () => {
29	  describe('whole document and member order', () => {
30	    runTable([
31	      ['path "" replaces the whole doc with an object', { a: 1 }, [add('', { z: 1 })], { z: 1 }],
32	      ['path "" replaces the whole doc with 5', { a: 1 }, [add('', 5)], 5],
33	      ['path "" replaces the whole doc with null', { a: 1 }, [add('', null)], null],
34	      ['a new member goes last', { a: 1 }, [add('/b', 2)], { a: 1, b: 2 }],
35	      ['an existing member keeps its place', { a: 1, b: 2 }, [add('/a', 3)], { a: 3, b: 2 }],
36	    ]);
37	
38	    test('an existing member keeps its place (keys)', () => {
39	      const result = applyPatch({ a: 1, b: 2 }, [add('/a', 3)]);
